const { chromium } = require('playwright');
const axe = require('axe-core');
const fs = require('fs');
const path = require('path');

(async () => {
    let browser;
    try {
        browser = await chromium.launch();
        const page = await browser.newPage();

        const html = fs.readFileSync(path.resolve('index.html'), 'utf8');
        await page.setContent(html, { waitUntil: 'load' });

        // Let React render (wait for #root to have children)
        await page.waitForFunction(() => {
            const root = document.getElementById('root');
            return root && root.children.length > 0;
        });

        // Inject axe-core
        await page.addScriptTag({ content: axe.source });

        const r = await page.evaluate(async () => await window.axe.run());

        const wcag = r.violations.filter(v => !(v.tags || []).includes('best-practice'));
        const bp = r.violations.filter(v => (v.tags || []).includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        if (wcag.length > 0) process.exit(1);
    } catch (e) {
        console.error(e);
        process.exit(1);
    } finally {
        if (browser) await browser.close();
    }
})();

